+/**
+ * Rehydrate authored overworld entrances that are absent from legacy saves.
+ * @param {import('../../../lib/ecs-js/index.js').World} world
+ * @param {number} worldSeed
+ * @returns {Promise<number>}
+ */
+export async function repairOverworldEntrances(world, worldSeed) {
+  const ow = await generateOverworldChunks(Number(worldSeed) >>> 0);
+  const existing = new Map();
+  for (const [id, identity, pos] of world.query(NamedIdentity, Position)) {
+    if (String(identity?.identity || '') !== 'stair_down') continue;
+    existing.set(`${Number(pos.x) | 0},${Number(pos.y) | 0}`, id);
+  }
+
+  let repaired = 0;
+  for (const chunk of ow.chunks || []) {
+    for (const spawn of chunk.spawns || []) {
+      if (String(spawn?.kind || '') !== 'stair_down') continue;
+      const templateId = String(spawn?.params?.entranceTemplateId || '');
+      const template = getUnderworldRegionTemplate(templateId);
+      if (!template) continue;
+      const x = Number(spawn.x) | 0;
+      const y = Number(spawn.y) | 0;
+      const key = `${x},${y}`;
+      let id = existing.get(key) || 0;
+      if (!(id > 0)) {
+        id = createFrom(world, StairDown, { x, y });
+        existing.set(key, id);
+      }
+      if (world.has(id, DungeonEntrance)) continue;
+      world.add(id, DungeonEntrance, {
+        templateId: template.templateId,
+        label: template.label,
+        type: template.type,
+        floors: template.floors,
+        biome: template.biome,
+        monsterTier: template.monsterTier,
+        lootTier: template.lootTier,
+        questId: template.questId,
+        lockId: String(template.lockId || ''),
+        lockDifficulty: String(template.lockDifficulty || ''),
+        targetDepth: template.targetDepth,
+        anchorX: x,
+        anchorY: y,
+      });
+      repaired++;
+    }
+  }
+  return repaired;
+}
